/*
 * A042271  Denominators of continued fraction convergents to sqrt(661).
 * https://oeis.org/A042271
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the n‑th convergent of the continued
 *            fraction of sqrt(661). The sequence is generated by the standard
 *            recurrence for continued fractions of a quadratic irrational.
 *            The recurrence uses the intermediate (m,d,a) values that satisfy
 *            m_{k+1} = d_k * a_k - m_k , d_{k+1} = (S - m_{...
 * Range:     u8 n <= 1, u16 n <= 9, u32 n <= 22, u64 n <= 41, u128 n <= 81,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of computed denominators */
    static seq_t *denoms = NULL;
    static size_t cap = 0;
    static idx_t last = (idx_t)-1;   /* last computed index */

    /* continued fraction state */
    static seq_t m = 0, d = 1;
    static seq_t prevprev = 1, prev = 0; /* q_{-2}=1, q_{-1}=0 */
    static const seq_t a0 = (seq_t)25;   /* floor(sqrt(661)) */
    static const seq_t S  = (seq_t)661;  /* the square root argument */

    /* initialise on first call */
    if (last == (idx_t)-1) {
        if (cap < 1) {
            cap = 1;
            denoms = (seq_t*)malloc(cap * sizeof(seq_t));
        }
        sequence_denom: /* compute for n = 0 */
        seq_t a_val = a0;                /* a_0 = 25 */
        seq_t q     = a_val * prev + prevprev;   /* q_0 = 25*0 + 1 = 1 */
        denoms[0]   = q;

        /* update CF state for next term */
        seq_t m_next = d * a_val - m;
        seq_t d_next = (S - m_next * m_next) / d;
        m = m_next;  d = d_next;
        prevprev = prev;
        prev = q;
        last = 0;
    }

    /* generate further terms if needed */
    while (last < n) {
        idx_t cur = last + 1;
        if (last + 2 > cap) {      /* grow cache */
            size_t newcap = cap ? cap << 1 : 1;
            seq_t *tmp = (seq_t*)realloc(denoms, newcap * sizeof(seq_t));
            denoms = tmp;
            cap = newcap;
        }

        seq_t a_val = (a0 + m) / d;           /* a_k = floor((a0 + m_k)/d_k) */
        seq_t q     = a_val * prev + prevprev;/* q_k = a_k*q_{k-1} + q_{k-2} */
        denoms[cur] = q;

        /* prepare state for next iteration */
        seq_t m_next = d * a_val - m;
        seq_t d_next = (S - m_next * m_next) / d;
        m = m_next;  d = d_next;

        prevprev = prev;
        prev = q;
        last = cur;
    }

    return denoms[n];
}
